#include <bits/stdc++.h>
using namespace std;struct State{long long h,q,a,g,t,s,e;};int main(int argc,char**argv){if(argc!=3)return 2;ifstream in(argv[1]);vector<State>C(80);for(auto&z:C)in>>z.h>>z.q>>z.a>>z.g>>z.t>>z.s>>z.e;const int LIM=1000000;vector<uint64_t>recipe(LIM/2+1);long long scanned=0;for(int m=0;m<=16;m++)for(int a=0;a<=m;a++){int b=m-a;for(int c=0;c<80;c++){int cut=c<16?c:(c-16)%32;for(int p=0;p<(1<<a);p++){if(a&&!(p>>(a-1)&1))continue;if(!a&&!cut)continue;State z=C[c];for(int i=0;i<a;i++){int eps=p>>i&1;z.t+=eps*(z.g+z.s);z.a+=eps*z.q;z.g=2*z.g+z.h*eps;z.q*=2;z.s=z.h*eps;}for(int r=0;r<(1<<b);r++){State w=z;for(int i=b-1;i>=0;i--){int eps=r>>i&1;w.t+=eps*(w.a+w.e);w.a=2*w.a+w.h*eps;w.g+=eps*w.q;w.q*=2;w.e=w.h*eps;}long long value=2*w.a+w.h-w.t;scanned++;if(value>=23&&value<=LIM&&!recipe[value/2]){if(value%2!=1)throw runtime_error("even");uint64_t packed=c|(uint64_t(a)<<7)|(uint64_t(b)<<12)|(uint64_t(p)<<17)|(uint64_t(r)<<33);recipe[value/2]=packed+1;}}}}}
ofstream out(argv[2],ios::binary);for(uint64_t x:recipe)for(int j=0;j<8;j++)out.put(char((x>>(8*j))&255));int covered=0;cout<<"{\"scanned\":"<<scanned<<",\"missing\":[";bool first=true;for(int n=23;n<=LIM;n+=2)if(!recipe[n/2]){if(!first)cout<<",";cout<<n;first=false;}else covered++;cout<<"],\"covered\":"<<covered<<"}"<<endl;}
